-- Netlabor initial schema (milestone M1). Every table from the data model.
-- IDs are UUIDv7 generated by the application; timestamps are timestamptz.

CREATE TABLE IF NOT EXISTS users (
  id uuid PRIMARY KEY,
  username text NOT NULL UNIQUE,
  email text,
  display_name text,
  password_hash text,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS oidc_providers (
  id uuid PRIMARY KEY,
  name text NOT NULL UNIQUE,
  issuer text NOT NULL,
  client_id text NOT NULL,
  client_secret_ciphertext bytea,
  client_secret_nonce bytea,
  scopes text[] NOT NULL DEFAULT ARRAY['openid','profile','email'],
  group_claim text NOT NULL DEFAULT 'groups',
  group_mappings jsonb NOT NULL DEFAULT '{}'::jsonb,
  default_role_id uuid,
  auto_create boolean NOT NULL DEFAULT false,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS user_identities (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider_id uuid NOT NULL REFERENCES oidc_providers(id) ON DELETE CASCADE,
  subject text NOT NULL,
  email text,
  PRIMARY KEY (provider_id, subject)
);
CREATE INDEX IF NOT EXISTS user_identities_user_idx ON user_identities(user_id);

CREATE TABLE IF NOT EXISTS sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  ip text,
  user_agent text,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);

CREATE TABLE IF NOT EXISTS api_keys (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name text NOT NULL,
  prefix text NOT NULL UNIQUE,
  key_hash text NOT NULL UNIQUE,
  scopes text[] NOT NULL DEFAULT '{}',
  project_ids uuid[] NOT NULL DEFAULT '{}',
  expires_at timestamptz,
  last_used_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS roles (
  id uuid PRIMARY KEY,
  name text NOT NULL UNIQUE,
  description text,
  builtin boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE oidc_providers
  ADD CONSTRAINT oidc_providers_default_role_fk
  FOREIGN KEY (default_role_id) REFERENCES roles(id) ON DELETE SET NULL;

CREATE TABLE IF NOT EXISTS role_privileges (
  role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  privilege text NOT NULL,
  PRIMARY KEY (role_id, privilege)
);

CREATE TABLE IF NOT EXISTS groups (
  id uuid PRIMARY KEY,
  name text NOT NULL UNIQUE,
  description text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS group_members (
  group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  PRIMARY KEY (group_id, user_id)
);

CREATE TABLE IF NOT EXISTS user_roles (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  PRIMARY KEY (user_id, role_id)
);

CREATE TABLE IF NOT EXISTS group_roles (
  group_id uuid NOT NULL REFERENCES groups(id) ON DELETE CASCADE,
  role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  PRIMARY KEY (group_id, role_id)
);

CREATE TABLE IF NOT EXISTS project_grants (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL,
  subject_type text NOT NULL CHECK (subject_type IN ('user','group')),
  subject_id uuid NOT NULL,
  role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id, subject_type, subject_id)
);

CREATE TABLE IF NOT EXISTS secrets (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  ciphertext bytea NOT NULL,
  nonce bytea NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS user_preferences (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  value jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS computes (
  id uuid PRIMARY KEY,
  name text NOT NULL UNIQUE,
  url text NOT NULL,
  token_hash text NOT NULL,
  underlay_index integer NOT NULL UNIQUE CHECK (underlay_index BETWEEN 1 AND 254),
  underlay_host text NOT NULL,
  status text NOT NULL DEFAULT 'offline' CHECK (status IN ('online','offline','error')),
  version text,
  capabilities jsonb,
  last_seen_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS pools (
  id uuid PRIMARY KEY,
  name text NOT NULL UNIQUE,
  description text
);

CREATE TABLE IF NOT EXISTS pool_computes (
  pool_id uuid NOT NULL REFERENCES pools(id) ON DELETE CASCADE,
  compute_id uuid NOT NULL REFERENCES computes(id) ON DELETE CASCADE,
  PRIMARY KEY (pool_id, compute_id)
);

CREATE TABLE IF NOT EXISTS images (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('qemu','iou','dynamips','docker','firmware')),
  filename text NOT NULL,
  sha256 text NOT NULL UNIQUE,
  size_bytes bigint NOT NULL,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS image_replicas (
  image_id uuid NOT NULL REFERENCES images(id) ON DELETE CASCADE,
  compute_id uuid NOT NULL REFERENCES computes(id) ON DELETE CASCADE,
  state text NOT NULL DEFAULT 'missing' CHECK (state IN ('present','syncing','missing')),
  path text,
  verified_at timestamptz,
  PRIMARY KEY (image_id, compute_id)
);

CREATE TABLE IF NOT EXISTS uploads (
  id uuid PRIMARY KEY,
  user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  filename text NOT NULL,
  sha256 text,
  size_bytes bigint NOT NULL,
  received_bytes bigint NOT NULL DEFAULT 0,
  state text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','complete','cancelled')),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS uploads_state_idx ON uploads(state);

CREATE TABLE IF NOT EXISTS templates (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  node_type text NOT NULL,
  category text NOT NULL DEFAULT 'General',
  symbol text NOT NULL DEFAULT 'router',
  default_name_format text NOT NULL DEFAULT '{name}-{index}',
  compute_id uuid REFERENCES computes(id) ON DELETE SET NULL,
  pool_id uuid REFERENCES pools(id) ON DELETE SET NULL,
  properties jsonb NOT NULL DEFAULT '{}'::jsonb,
  builtin boolean NOT NULL DEFAULT false,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS template_base_configs (
  template_id uuid NOT NULL REFERENCES templates(id) ON DELETE CASCADE,
  filename text NOT NULL,
  content text NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (template_id, filename)
);

CREATE TABLE IF NOT EXISTS project_templates (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  description text,
  topology jsonb NOT NULL,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS symbols (
  id text PRIMARY KEY,
  name text NOT NULL UNIQUE,
  svg text NOT NULL,
  theme text,
  builtin boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS settings (
  key text PRIMARY KEY,
  value jsonb NOT NULL
);

CREATE TABLE IF NOT EXISTS projects (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  description text,
  status text NOT NULL DEFAULT 'closed' CHECK (status IN ('closed','opened')),
  locked boolean NOT NULL DEFAULT false,
  owner_id uuid NOT NULL REFERENCES users(id),
  pool_id uuid REFERENCES pools(id) ON DELETE SET NULL,
  variables jsonb NOT NULL DEFAULT '{}'::jsonb,
  scene jsonb NOT NULL DEFAULT '{}'::jsonb,
  auto_open boolean NOT NULL DEFAULT false,
  auto_close boolean NOT NULL DEFAULT false,
  auto_start boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS projects_owner_idx ON projects(owner_id);
CREATE INDEX IF NOT EXISTS projects_status_idx ON projects(status);

CREATE TABLE IF NOT EXISTS project_slots (
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  compute_id uuid NOT NULL REFERENCES computes(id) ON DELETE CASCADE,
  slot integer NOT NULL CHECK (slot BETWEEN 1 AND 254),
  netns text NOT NULL,
  project_ip inet NOT NULL,
  PRIMARY KEY (compute_id, slot),
  UNIQUE (project_id, compute_id)
);

CREATE TABLE IF NOT EXISTS nodes (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  compute_id uuid NOT NULL REFERENCES computes(id),
  name text NOT NULL,
  symbol text NOT NULL,
  node_type text NOT NULL,
  template_id uuid REFERENCES templates(id) ON DELETE SET NULL,
  x double precision NOT NULL DEFAULT 0,
  y double precision NOT NULL DEFAULT 0,
  z integer NOT NULL DEFAULT 0,
  layer text NOT NULL DEFAULT 'default',
  locked boolean NOT NULL DEFAULT false,
  isolated boolean NOT NULL DEFAULT false,
  console_port integer,
  console_type text NOT NULL DEFAULT 'telnet',
  console_auto_start boolean NOT NULL DEFAULT true,
  properties jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'stopped' CHECK (status IN ('stopped','started','suspended','error')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS nodes_project_idx ON nodes(project_id);
CREATE INDEX IF NOT EXISTS nodes_compute_idx ON nodes(compute_id);

CREATE TABLE IF NOT EXISTS links (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  link_type text NOT NULL CHECK (link_type IN ('ethernet','serial','atm','frame_relay')),
  node_a_id uuid NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,
  adapter_a integer NOT NULL,
  port_a integer NOT NULL,
  node_b_id uuid NOT NULL REFERENCES nodes(id) ON DELETE CASCADE,
  adapter_b integer NOT NULL,
  port_b integer NOT NULL,
  suspend boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','suspended','error')),
  style jsonb NOT NULL DEFAULT '{}'::jsonb,
  filters jsonb NOT NULL DEFAULT '{}'::jsonb,
  capture jsonb,
  dataplane jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS links_project_idx ON links(project_id);
CREATE INDEX IF NOT EXISTS links_node_a_idx ON links(node_a_id);
CREATE INDEX IF NOT EXISTS links_node_b_idx ON links(node_b_id);

CREATE TABLE IF NOT EXISTS drawings (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  type text NOT NULL CHECK (type IN ('rect','ellipse','line','text','note','image')),
  svg text,
  text text,
  file_path text,
  x double precision NOT NULL DEFAULT 0,
  y double precision NOT NULL DEFAULT 0,
  width double precision NOT NULL DEFAULT 100,
  height double precision NOT NULL DEFAULT 100,
  rotation double precision NOT NULL DEFAULT 0,
  z integer NOT NULL DEFAULT 0,
  layer text NOT NULL DEFAULT 'default',
  locked boolean NOT NULL DEFAULT false,
  style jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE INDEX IF NOT EXISTS drawings_project_idx ON drawings(project_id);

CREATE TABLE IF NOT EXISTS markers (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  link_id uuid NOT NULL REFERENCES links(id) ON DELETE CASCADE,
  name text NOT NULL,
  bpf text NOT NULL,
  tag integer NOT NULL,
  color text NOT NULL,
  highlight_duration integer NOT NULL DEFAULT 1000,
  direction text CHECK (direction IN ('tx','rx')),
  enabled boolean NOT NULL DEFAULT true,
  paused boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (link_id, name)
);
CREATE INDEX IF NOT EXISTS markers_link_idx ON markers(link_id);

CREATE TABLE IF NOT EXISTS faults (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind text NOT NULL,
  target jsonb NOT NULL DEFAULT '{}'::jsonb,
  params jsonb NOT NULL DEFAULT '{}'::jsonb,
  state text NOT NULL DEFAULT 'active',
  recovery jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  cleared_at timestamptz
);

CREATE TABLE IF NOT EXISTS snapshots (
  id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name text NOT NULL,
  description text,
  sha256 text NOT NULL,
  size_bytes bigint NOT NULL,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS port_allocations (
  compute_id uuid NOT NULL REFERENCES computes(id) ON DELETE CASCADE,
  port integer NOT NULL,
  kind text NOT NULL CHECK (kind IN ('console','aux','vnc','marker','link','iou_app')),
  side text,
  owner_id uuid,
  PRIMARY KEY (compute_id, port)
);

CREATE TABLE IF NOT EXISTS jobs (
  id uuid PRIMARY KEY,
  kind text NOT NULL,
  state text NOT NULL DEFAULT 'running' CHECK (state IN ('running','completed','failed','cancelled')),
  progress double precision NOT NULL DEFAULT 0,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  result jsonb,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS jobs_state_idx ON jobs(state);

CREATE TABLE IF NOT EXISTS events (
  id bigserial PRIMARY KEY,
  project_id uuid,
  user_id uuid,
  type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS events_project_idx ON events(project_id, id);
CREATE INDEX IF NOT EXISTS events_user_idx ON events(user_id, id);
CREATE INDEX IF NOT EXISTS events_created_idx ON events(created_at);

CREATE TABLE IF NOT EXISTS audit_log (
  id bigserial PRIMARY KEY,
  user_id uuid,
  action text NOT NULL,
  resource_type text NOT NULL,
  resource_id text,
  project_id uuid,
  data jsonb NOT NULL DEFAULT '{}'::jsonb,
  ip text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS audit_created_idx ON audit_log(created_at);

-- Projects referenced by grants cascade on delete; the constraint is added
-- after both tables exist.
ALTER TABLE project_grants
  DROP CONSTRAINT IF EXISTS project_grants_project_fk;
ALTER TABLE project_grants
  ADD CONSTRAINT project_grants_project_fk
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE;
